interface Printable{String printLabel();}class PackageBox implements Printable{String id;PackageBox(String i){id=i;}public String printLabel(){return "Package label: "+id;}}class Invoice implements Printable{String number;Invoice(String n){number=n;}public String printLabel(){return "Invoice label: "+number;}}public class Main{static void printAll(Printable[] x){for(Printable p:x)System.out.println(p.printLabel());}public static void main(String[]a){}}